INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.79.0',
  '2026-08-31',
  'Меню и главная: заполненные страницы сверху, закрепление кнопкой 📌',
  E'Страниц стало под три десятка, и нужная тонула среди тех, в которые ни разу не заходили. Теперь меню и плитки на главной сортируются сами: сверху закреплённые, дальше страницы, где у вас есть данные, внизу пустые — они отделены подписью «без данных».\n\nЗакрепить страницу вверху можно кнопкой 📌 у правого края пункта меню, повторное нажатие открепляет. Закреплённые идут в том порядке, в котором вы их закрепляли, и на главной помечены той же скрепкой.\n\nНичего не прячется — меняется только порядок, весь список на месте. Порядок обновляется при следующем запуске: страница, где вы только что завели первую запись, поднимется наверх не сразу.',
  E'Порядок общий у меню и плиток: shared/pageOrder.ts (sortPages/pageRank), обе страницы зовут одну функцию — иначе меню и главная разъехались бы, как уже расходился набор страниц до v2.77.\n\nПризнак «есть данные» считает сервер: GET /me/pages/order, один запрос с EXISTS по главной таблице каждой страницы (store/pageorder.go, карта pageDataSources). Главная таблица, а не все: вопрос «начинал ли пользоваться», а не «сколько строк». Несколько таблиц через ИЛИ там, где разделы независимы (в Food можно вести только рецепты). Страница без источника (Settings, Help, админские) всегда пустая и уезжает вниз.\n\nЗакрепление — user_settings.menu_pinned_pages (миграция 0107), PUT /me/pages/pinned заменяет список целиком, порядок списка = порядок закреплённых. Колонка отдельная: pinned_pages из 0074 занята липкой шапкой, мешать разные смыслы в одной колонке значит напрашиваться на ошибку. Неизвестные коды и дубли на записи молча отсеиваются (клиент мог остаться на старой версии), больше 32 — 400.\n\nlocalStorage остался кэшем на первый кадр: без него плитки успевали нарисоваться в исходном порядке и прыгали после ответа сервера. Запись оптимистичная, при ошибке откат и тост.\n\nВёрстка: кнопка 📌 лежит НАД пунктом меню (position: absolute), а не внутри — кнопка в кнопке невалидна; пункту добавлен padding-right, чтобы длинное имя не заезжало под скрепку.'
);
-- +goose StatementEnd

